using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CheckSevenDependencies{public static string Main(){var data=new Dictionary<string,(float y,float ground)>();string Key(Collider c)=>c.name+":"+c.transform.position.x.ToString("F2")+":"+c.transform.position.z.ToString("F2");bool Local(Collider c){var p=c.bounds.center;return p.x>100&&p.x<450&&p.z>-85&&p.z<140&&!c.isTrigger&&!c.name.StartsWith("Ground_")&&!c.GetComponentInParent<ArcadeVehicle>()&&(c.name.Contains("Tree")||c.name.Contains("tree")||System.Text.RegularExpressions.Regex.IsMatch(c.name,@"\b(house|garage|kennel|shed|fence|gate|pool|post|sign)\b",System.Text.RegularExpressions.RegexOptions.IgnoreCase));}float Ground(Collider c){var p=c.bounds.center;p.y=c.bounds.min.y;return Physics.RaycastAll(p+Vector3.up*3,Vector3.down,15,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).Select(h=>h.point.y).DefaultIfEmpty(p.y).Max();}
EditorSceneManager.OpenScene("Assets/Scenes/SevenBaseline.unity");Physics.SyncTransforms();foreach(var c in Object.FindObjectsByType<Collider>().Where(Local))data[Key(c)]=(c.bounds.min.y,Ground(c));var samples=new List<(Vector3 p,float y)>();var road=Object.FindAnyObjectByType<RaceDirector>().road;road.Initialize();for(float s=0;s<road.Length;s+=3){var p=road.At(s,out _);if(p.x>345&&p.x<403&&p.z>-20&&p.z<10)continue;var hits=Physics.RaycastAll(p+Vector3.up*2,Vector3.down,5,1).Where(h=>h.collider.name.StartsWith("Ground_")).ToArray();if(hits.Length>0)samples.Add((p,hits.Max(h=>h.point.y)));}
EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var rows=new List<string>();int count=0;float maxWorse=0;foreach(var c in Object.FindObjectsByType<Collider>().Where(Local)){if(!data.TryGetValue(Key(c),out var old))continue;count++;float y=Ground(c),gap=c.bounds.min.y-y,oldgap=old.y-old.ground;float worse=Mathf.Abs(gap)-Mathf.Abs(oldgap);maxWorse=Mathf.Max(maxWorse,worse);if(Mathf.Abs(y-old.ground)>.03f||Mathf.Abs(c.bounds.min.y-old.y)>.03f)rows.Add(c.name+$" groundDelta={y-old.ground:F3} oldGap={oldgap:F3} newGap={gap:F3}");}float maxRoad=0;int missing=0;foreach(var s in samples){var hits=Physics.RaycastAll(s.p+Vector3.up*2,Vector3.down,5,1).Where(h=>h.collider.name.StartsWith("Ground_")).ToArray();if(hits.Length==0){missing++;continue;}maxRoad=Mathf.Max(maxRoad,Mathf.Abs(hits.Max(h=>h.point.y)-s.y));}rows.Insert(0,$"Compared {count} existing grounded colliders; maximum increased absolute foot gap={maxWorse:F4}; main road samples outside authorized jump={samples.Count}, missing={missing}, maxDelta={maxRoad:F4}");File.WriteAllLines("Docs/SevenCorrections/dependencies.txt",rows);AssetDatabase.DeleteAsset("Assets/Scenes/SevenBaseline.unity");return string.Join("\n",rows);}}

